entry.update(status='UNFINISHED',generation_ready=True,current_step='record_item_acceptance_from_all_fittings',art_review=dict(status='PASS',reason=review),native_acceptance='Pending full-set gate, explicit-west direction binding and combined outfit precedence',known_issues=['Native four-facing criterion remains unsatisfied: current side-direction mapping needs explicit west optical/head-depth binding in final integration.','Source does not prescribe exact ocular handedness; the same authored eye is retained throughout.']);entry['apparel_workflow']['status']='GENERATION READY'
